import math

def solve():
    option_type = "call"
    asset_price = 150.0
    strike_price = 140.0
    time_to_expiry = 0.5
    volatility = 0.25
    risk_free_rate = 0.02

    # Helper function for the standard normal cumulative distribution function (CDF)
    # equivalent to scipy.stats.norm.cdf
    def norm_cdf(x):
        return 0.5 * (1 + math.erf(x / math.sqrt(2.0)))

    # Calculate d1
    d1 = (math.log(asset_price / strike_price) + (risk_free_rate + 0.5 * volatility ** 2) * time_to_expiry) / \
         (volatility * math.sqrt(time_to_expiry))

    # Calculate delta based on option type
    if option_type.lower() == 'call':
        delta = norm_cdf(d1)
    elif option_type.lower() == 'put':
        delta = norm_cdf(d1) - 1
    else:
        raise ValueError("Invalid option type. Must be 'call' or 'put'.")

    return round(delta, 4)

